import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const A=JSON.parse('{"title":"Sequence Flow — Add Workspace Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-19-add-workspace-member/sequence-flow.md","filePath":"feature/agency-workspace/3-4-19-add-workspace-member/sequence-flow.md"}'),r={name:"feature/agency-workspace/3-4-19-add-workspace-member/sequence-flow.md"};function s(d,e,n,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-add-workspace-member" tabindex="-1">Sequence Flow — Add Workspace Member <a class="header-anchor" href="#sequence-flow-—-add-workspace-member" aria-label="Permalink to &quot;Sequence Flow — Add Workspace Member&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.19). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-23.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — the MANAGER of the Workspace, adding the member.</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding invitation, membership, Agency membership, and user records.</li><li><strong>Notification service</strong> — sends the invitation email.</li></ul><hr><h2 id="flow-a-—-invite-by-email" tabindex="-1">Flow A — Invite by email <a class="header-anchor" href="#flow-a-—-invite-by-email" aria-label="Permalink to &quot;Flow A — Invite by email&quot;">​</a></h2><ol><li>Client → System: on <code>/workspaces/:id/members</code>, choose &quot;Add Member&quot;, open the &quot;Invite by email&quot; tab, and fill in the email, the role, and an optional note.</li><li>System: check the caller&#39;s role in the Workspace before handling the request — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System: validate the request — a missing or malformed email, or a missing role, is rejected with 400 <code>VALIDATION_ERROR</code>.</li><li>System: normalise the email address.</li><li>System → Database: check whether the email already belongs to an active member of the Workspace; if so, reject with 409 <code>ALREADY_IN_WORKSPACE</code>.</li><li>System → Database: check whether a pending, unexpired invitation already exists for that email in the Workspace; if so, reject with 409 <code>INVITATION_ALREADY_PENDING</code>.</li><li>System → Database (when the role is MANAGER): count the Workspace&#39;s active MANAGERs; a count above zero is rejected with 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>System → Database: insert the invitation with a pending status, a random token, and an expiry.</li><li>System → Notification service: send the invitation email carrying the Workspace name, the token, and the note.</li><li>System → Client: confirmation that the invitation has been sent — no invitation details are returned.</li></ol><h3 id="sub-flow-—-accept-the-invitation" tabindex="-1">Sub-flow — Accept the invitation <a class="header-anchor" href="#sub-flow-—-accept-the-invitation" aria-label="Permalink to &quot;Sub-flow — Accept the invitation&quot;">​</a></h3><ol><li>Invitee follows the email link; Client → System: submit the invitation token.</li><li>System: validate the token, its status, its expiry, and that it matches the invitee; when the invitation carries the MANAGER role and the Workspace already has an active MANAGER, reject with 409 <code>MANAGER_ALREADY_ASSIGNED</code>; when the email is already an active member, reject with 409 <code>ALREADY_IN_WORKSPACE</code>.</li><li>System → Database: insert the membership row with the invited role and mark the invitation accepted.</li><li>System → Client: the created member entry.</li></ol><h2 id="flow-b-—-assign-directly" tabindex="-1">Flow B — Assign directly <a class="header-anchor" href="#flow-b-—-assign-directly" aria-label="Permalink to &quot;Flow B — Assign directly&quot;">​</a></h2><ol><li>Client → System: open the &quot;Assign from Agency&quot; tab, pick one or more existing Agency members, and choose a role for each.</li><li>System: check the caller&#39;s role — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System: validate the request — an empty member list is rejected with 400 <code>VALIDATION_ERROR</code>.</li><li>System: for each entry: <ul><li>System → Database: check the entry&#39;s user is an Agency member; if not, reject with 403 <code>NOT_AGENCY_MEMBER</code>.</li><li>System → Database: check whether the user already has an active membership in the Workspace; if so, add the identifier to the skipped list and move on without error.</li><li>System → Database (when the entry requests MANAGER): count the Workspace&#39;s active MANAGERs; a count above zero is rejected with 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>System → Database: read the user record; a missing user raises <code>USER_NOT_FOUND</code>.</li><li>System → Database: insert the membership row as active immediately, and add it to the added list.</li></ul></li><li>System → Client: the members added together with the identifiers that were skipped because those users were already active members.</li><li>Client: refresh the member table with the members added and show a notice for the skipped users.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Invite / Assign</td><td>Caller is not the MANAGER of the Workspace</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Invite</td><td>Email already belongs to an active member</td><td>409</td><td><code>ALREADY_IN_WORKSPACE</code></td></tr><tr><td>Invite</td><td>A pending invitation already exists for the email</td><td>409</td><td><code>INVITATION_ALREADY_PENDING</code></td></tr><tr><td>Invite / Assign</td><td>MANAGER role requested while the Workspace already has an active MANAGER</td><td>409</td><td><code>MANAGER_ALREADY_ASSIGNED</code></td></tr><tr><td>Assign</td><td>Entry&#39;s user is not an Agency member</td><td>403</td><td><code>NOT_AGENCY_MEMBER</code></td></tr><tr><td>Assign</td><td>Entry&#39;s user does not exist</td><td>—</td><td><code>USER_NOT_FOUND</code></td></tr><tr><td>Invite</td><td>Email missing or malformed, or role missing</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Assign</td><td>Member list empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The invitation path does not create a membership — the invitee must accept before becoming a member; the assignment path creates active memberships immediately.</li><li>Both paths enforce the single-MANAGER rule, so a Workspace never has more than one active MANAGER.</li><li>Users who are already active members are reported in the skipped list rather than silently ignored; the rest of the batch is still processed.</li></ul>',16)])])}const p=t(r,[["render",s]]);export{A as __pageData,p as default};
